BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create function pg_temp.i(n int)returns uuid language sql immutable as $$select('ee730000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create temp table st(k text primary key,v jsonb);grant all on st,assertion_count to service_role;
insert into public.organizations(id,name)values(pg_temp.i(1),'Pipeline SQL fixture'),(pg_temp.i(2),'Pipeline other fixture');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)select pg_temp.i(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','pipeline-'||n||'@fixture.invalid',clock_timestamp(),clock_timestamp(),clock_timestamp()from generate_series(101,104)n;
insert into public.profiles(id,org_id,role)select pg_temp.i(n),pg_temp.i(case when n=103 then 2 else 1 end),case when n=102 then'viewer'else'admin'end from generate_series(101,104)n on conflict(id)do update set org_id=excluded.org_id,role=excluded.role;
insert into public.properties(id,org_id,name)values(pg_temp.i(201),pg_temp.i(1),'Pipeline SQL property'),(pg_temp.i(202),pg_temp.i(2),'Pipeline other property');
insert into public.ad_account_connections(id,property_id,platform,account_id,account_name,is_active)values(pg_temp.i(401),pg_temp.i(201),'google_ads','1111111111','Synthetic account',true),(pg_temp.i(402),pg_temp.i(202),'meta_ads','2222222222','Other account',true);
create function pg_temp.command(n int,input jsonb,a int default 101)returns jsonb language plpgsql as $$declare r jsonb;begin r:=public.decide_pipeline(pg_temp.i(n),pg_temp.i(a),pg_temp.i(201),input);perform set_config('p11.pipeline_decision','',true);perform set_config('p11.pipeline_scope','',true);return r;end$$;
create function pg_temp.start_it(n int,a int default 101)returns jsonb language sql as $$select pg_temp.command(n,jsonb_build_object('operation','start','connectionsHash',public.read_pipelines(pg_temp.i(101),pg_temp.i(201),'{}')->>'connectionsHash','connectionIds',jsonb_build_array(pg_temp.i(401)),'dateRange','LAST_30_DAYS'),a)$$;
create function pg_temp.control(n int,op text,j int,revision int default null)returns jsonb language sql as $$select pg_temp.command(n,jsonb_build_object('operation',op,'jobId',pg_temp.i(j),'revision',coalesce(revision,(select revision from public.import_jobs where id=pg_temp.i(j))),'note','Fixture progress decision'))$$;
create function pg_temp.read_it(kind text default'list',n int default null,a int default 101,offset_n int default 0)returns jsonb language sql as $$select public.read_pipelines(pg_temp.i(a),pg_temp.i(201),jsonb_build_object('kind',kind,'id',pg_temp.i(n),'offset',offset_n))$$;
set local role service_role;
select pg_temp.check_it(pg_temp.start_it(301,102)->>'state'='forbidden','viewer cannot start');
select pg_temp.check_it(pg_temp.start_it(301,103)->>'state'='forbidden','other organization cannot start');
select pg_temp.check_it(pg_temp.command(301,jsonb_build_object('operation','start','connectionsHash',public.read_pipelines(pg_temp.i(101),pg_temp.i(201),'{}')->>'connectionsHash','connectionIds',jsonb_build_array(pg_temp.i(402)),'dateRange','LAST_30_DAYS'))->>'state'='accounts_changed','cross property source rejected');
select pg_temp.check_it(pg_temp.command(301,'{"operation":"start","connectionIds":[],"dateRange":"LAST_30_DAYS"}')->>'state'='invalid_input','empty source rejected');
select pg_temp.check_it(pg_temp.start_it(301)->>'status'='pending','human request saved');
select pg_temp.check_it(pg_temp.start_it(301)->>'state'='replayed','lost start reply reused');
select pg_temp.check_it(pg_temp.start_it(301,104)->>'state'='not_found','other manager cannot recover private request');
select pg_temp.check_it(pg_temp.command(301,jsonb_build_object('operation','start','connectionsHash',public.read_pipelines(pg_temp.i(101),pg_temp.i(201),'{}')->>'connectionsHash','connectionIds',jsonb_build_array(pg_temp.i(401)),'dateRange','TODAY'))->>'state'='request_conflict','same identity cannot change source period');
select pg_temp.check_it(pg_temp.start_it(302)->>'state'='open_import','overlapping human start held');
select pg_temp.check_it(pg_temp.read_it('job',301)#>>'{accounts,0,account_id}'='1111111111','account identity frozen on acceptance');
select pg_temp.check_it(pg_temp.command(350,jsonb_build_object('operation','start','connectionIds',jsonb_build_array(pg_temp.i(401)),'dateRange','TODAY','connectionsHash',repeat('a',64)))->>'state'='accounts_changed','changed source choice cannot silently bind');
select pg_temp.check_it(pg_temp.read_it('job',301)#>>'{job,requested_actor_id}'=pg_temp.i(101)::text,'request actor retained');
select pg_temp.check_it(not(pg_temp.read_it('job',301)->'job'?'lease_token'),'worker token never exposed');
select pg_temp.check_it(pg_temp.read_it('job',301,102)->>'state'='ready','viewer can inspect progress');
select pg_temp.check_it(pg_temp.read_it('job',301,103)->>'state'='forbidden','other org cannot inspect progress');
select pg_temp.check_it(pg_temp.read_it('command',301,104)->>'state'='not_found','command recovery private');
select pg_temp.check_it(public.claim_marketing_import(pg_temp.i(301),pg_temp.i(501))#>>'{job,status}'='running','worker obtains actual lease');
select pg_temp.check_it(public.claim_marketing_import(pg_temp.i(301),pg_temp.i(502))is null,'second worker cannot claim live lease');
select pg_temp.check_it(pg_temp.control(303,'stop',301,1)->>'state'='job_changed','stale stop held');
select pg_temp.check_it(pg_temp.control(303,'stop',301)->>'status'='cancelled','current stop fences lease');
select pg_temp.check_it(public.claim_marketing_import(pg_temp.i(301),pg_temp.i(502))is null,'stopped job cannot restart');
select pg_temp.throws(format('select public.renew_marketing_import(%L,%L)',pg_temp.i(301),pg_temp.i(501)),'late heartbeat fenced');
select pg_temp.throws(format('select public.save_marketing_import_report(%L,%L,%L,%L)',pg_temp.i(301),pg_temp.i(501),pg_temp.i(401),'[]'),'late report fenced');
select pg_temp.check_it(pg_temp.command(303,'{"operation":"cancel_request"}')->>'status'='cancelled','cancel cannot erase completed stop');
select pg_temp.check_it(pg_temp.control(304,'review',301)->>'status'='reviewed','review retained without falsifying job status');
select pg_temp.check_it(pg_temp.read_it('job',301)#>>'{job,status}'='cancelled','review does not mark import complete');
select pg_temp.check_it(pg_temp.read_it('history',301)#>>'{items,0,note}'='Fixture progress decision','review explanation visible');
select pg_temp.check_it(pg_temp.control(305,'retry',301)->>'status'='pending','retry creates new linked request');
select pg_temp.check_it(pg_temp.read_it('job',305)#>>'{job,retry_of}'=pg_temp.i(301)::text,'retry ancestry retained');
select pg_temp.check_it(pg_temp.read_it('job',305)#>>'{job,reference_at}'=pg_temp.read_it('job',301)#>>'{job,reference_at}','retry preserves exact relative-date anchor');
select pg_temp.check_it(public.claim_marketing_import(pg_temp.i(305),pg_temp.i(505))#>>'{job,status}'='running','retry claimed separately');
select public.save_marketing_import_report(pg_temp.i(305),pg_temp.i(505),pg_temp.i(401),jsonb_build_array(jsonb_build_object('property_id',pg_temp.i(201),'date','2026-09-01','channel_id','google_ads','source_account_id','1111111111','currency_code','USD','campaign_id','fixture','campaign_name','Fixture','impressions',100,'clicks',10,'spend',1.25,'conversions',0.125)));
select pg_temp.check_it(pg_temp.read_it('job',305)#>>'{accounts,0,reportRows}'='1','retained report count truthful');
select pg_temp.check_it(not(pg_temp.read_it('job',305)#>'{accounts,0}'?'records'),'raw source report not exposed');
select pg_temp.check_it(public.commit_marketing_import_batch(pg_temp.i(305),pg_temp.i(505),pg_temp.i(401))->>'offset'='1','batch committed');
select pg_temp.check_it(public.commit_marketing_import_batch(pg_temp.i(305),pg_temp.i(505),pg_temp.i(401))->>'offset'='1','lost batch reply never duplicates count');
select pg_temp.check_it(public.finish_marketing_import(pg_temp.i(305),pg_temp.i(505))='complete','all account checkpoints finish');
select pg_temp.check_it(pg_temp.read_it('job',305)#>>'{job,records_imported}'='1','confirmed count retained');
select pg_temp.check_it((select conversions=0.125 and spend=1.25 from public.fact_marketing_performance where property_id=pg_temp.i(201)),'actual facts preserve fractional attribution and cents');
select pg_temp.check_it(pg_temp.control(306,'retry',305)->>'state'='retry_unavailable','completed import cannot masquerade as recovery');
select pg_temp.check_it(pg_temp.command(306,'{"operation":"cancel_request"}')->>'status'='cancelled_request','unused cancellation retained');
select pg_temp.check_it(pg_temp.start_it(306)->>'status'='cancelled_request','late original request fenced');
select pg_temp.check_it(pg_temp.start_it(307)->>'status'='pending','another fresh import allowed after completion');
update public.ad_account_connections set account_id='3333333333'where id=pg_temp.i(401);
select pg_temp.check_it(public.claim_marketing_import(pg_temp.i(307),pg_temp.i(507))is null,'changed source prevents provider invocation');
select pg_temp.check_it(pg_temp.read_it('job',307)->>'workerHold'is not null,'source hold is visible');
select pg_temp.check_it(pg_temp.control(308,'stop',307)->>'status'='cancelled','changed source still stoppable');
select pg_temp.check_it(pg_temp.control(309,'retry',307)->>'state'='accounts_changed','retry cannot silently rebind account');
update public.ad_account_connections set account_id='1111111111'where id=pg_temp.i(401);
select pg_temp.start_it(310);
reset role;select set_config('p11.team_scope',pg_temp.i(1)::text,true);update public.profiles set role='viewer'where id=pg_temp.i(101);set local role service_role;
select pg_temp.check_it(public.claim_marketing_import(pg_temp.i(310),pg_temp.i(510))is null,'revoked requester prevents worker start');
select pg_temp.check_it(pg_temp.read_it('job',310)->>'workerHold'is not null,'permission hold is visible');
select pg_temp.check_it(pg_temp.start_it(310)->>'state'='forbidden','revoked permission denies replay');
reset role;update public.profiles set role='admin'where id=pg_temp.i(101);set local role service_role;
select pg_temp.control(311,'stop',310);
select pg_temp.check_it((select count(*)from public.pipeline_commands where property_id=pg_temp.i(201))=(select count(*)from public.shared_action_events where property_id=pg_temp.i(201)and actor_id is not null),'human decisions atomically recorded');
select pg_temp.check_it((select count(*)>3 from public.shared_action_events where property_id=pg_temp.i(201)and service_principal='pipelines.import_worker'),'actual worker events separately attributed');
select pg_temp.check_it((select bool_and(not training_eligible)from public.shared_action_events where property_id=pg_temp.i(201)),'no import event is a training reward');
select set_config('p11.pipeline_worker','',true);select set_config('p11.pipeline_scope','',true);
select pg_temp.throws(format('update public.import_jobs set status=%L where id=%L','pending',pg_temp.i(301)),'service cannot revive stopped request');
select pg_temp.throws(format('update public.pipeline_events set action=%L where job_id=%L','forged',pg_temp.i(301)),'event history immutable');
select pg_temp.throws(format('delete from public.pipeline_commands where id=%L',pg_temp.i(301)),'live command retention protected');
-- Service-origin acceptance is attributable without forging a human decision.
insert into public.import_jobs(id,property_id,channels,date_range,status,recovery_version)values(pg_temp.i(320),pg_temp.i(201),array['google_ads'],'LAST_7_DAYS','pending',1);
select pg_temp.check_it((select requested_actor_id is null and control_version=1 from public.import_jobs where id=pg_temp.i(320)),'service request remains distinct from human');
select pg_temp.check_it((select count(*)=1 from public.pipeline_events where job_id=pg_temp.i(320)and action='pipeline.import.queued'and actor_id is null),'service acceptance action saved');
select pg_temp.control(321,'stop',320);
-- Complete history is reachable, with drift protection.
do $$begin for n in 4000..4021 loop perform pg_temp.control(n,'review',301);end loop;end$$;
select pg_temp.check_it(jsonb_array_length(pg_temp.read_it('history',301)->'items')=20,'history first page bounded');
select pg_temp.check_it(jsonb_array_length(pg_temp.read_it('history',301,101,20)->'items')>0,'history remaining page reachable');
insert into st values('history',pg_temp.read_it('history',301));select pg_temp.control(4022,'review',301);
select pg_temp.check_it(public.read_pipelines(pg_temp.i(101),pg_temp.i(201),jsonb_build_object('kind','history','id',pg_temp.i(301),'expectedHash',(select v->>'hash'from st where k='history')))->>'state'='history_changed','changed history cannot silently skip records');
reset role;
select pg_temp.check_it(not has_table_privilege('authenticated','public.pipeline_commands','SELECT'),'private command data service-only');
select pg_temp.check_it(not has_function_privilege('authenticated','public.decide_pipeline(uuid,uuid,uuid,jsonb)','EXECUTE'),'native controls service-only');
select n as assertions_passed from assertion_count;ROLLBACK;
